VRT_L("1re-a-maths-r01",{"duree":20,"titre":"Équations et inéquations homographiques","accroche":"Un quotient égal à un nombre.","intro":"Une fonction homographique est un quotient de deux expressions du premier degré. On résout ses équations en écartant la valeur interdite.","objectifs":["trouver la valeur interdite","résoudre une équation quotient","résoudre une inéquation quotient"],"parties":[{"t":"Définition","html":"<div class='def'><b>Définition</b>Une <strong>fonction homographique</strong> s'écrit f(x) = (ax + b)/(cx + d) avec c ≠ 0. Elle n'est pas définie pour cx + d = 0 : c'est la <strong>valeur interdite</strong>.</div>"},{"t":"Équation","html":"<p>(2x − 1)/(x + 3) = 1, avec x ≠ −3 : 2x − 1 = x + 3, donc x = 4.</p>","retenir":"On écarte toujours la valeur interdite.","labo":{"type":"courbe","fn":"inv","xmin":-4,"xmax":4,"ymin":-4,"ymax":4,"x0":1}},{"t":"Inéquation","html":"<p>(x − 1)/(x + 2) ≥ 0 se résout avec un tableau de signes : x ∈ ]−∞ ; −2[ ∪ [1 ; +∞[.</p>"},{"t":"Entraînement au format de l'examen","html":"<div class='integ'><h3>Partie A : évaluation des ressources</h3><p><strong>Question de cours.</strong> L'équation (2x − 1)/(x + 3) = 1 a pour condition d'existence :</p><ol type='a'><li>x ≠ −3</li><li>x ≠ 1/2</li><li>x ≠ 3</li><li>aucune condition</li></ol><details><summary>Voir la réponse</summary><p><strong>x ≠ −3</strong>. Le dénominateur x + 3 ne doit pas s'annuler, donc x ≠ −3.</p></details><p><strong>Exercice.</strong></p><p>Résous (x + 1)/(x − 2) = 2.</p><details><summary>Voir la réponse</summary><p>(Réponse : x = 5.)</p></details><h3>Partie B : évaluation des compétences</h3><p><strong>Situation.</strong> Un loueur de motos de Bertoua facture 2 000 F de frais fixes, plus 1 500 F par jour de location. Le prix moyen par jour pour x jours est p(x) = (1 500x + 2 000)/x.</p><p><strong>Tâche 1.</strong> Pour combien de jours le prix moyen est-il de 1 750 F ?</p><p><strong>Tâche 2.</strong> Pour quelles durées le prix moyen est-il inférieur ou égal à 1 700 F ?</p><details><summary>Voir une réponse attendue</summary><p>1 500x + 2 000 = 1 750x donne x = 8 jours. Pour x > 0 : 1 500x + 2 000 ≤ 1 700x ⇔ 2 000 ≤ 200x ⇔ x ≥ 10 jours.</p></details></div>","retenir":"Savoir-être mobilisé : Rigueur dans la rédaction."}],"revision":["Valeur interdite.","Produit en croix.","Tableau de signes."],"exo":"<p>Résous (x + 1)/(x − 2) = 2. <em>(Réponse : x = 5.)</em></p>","quiz":[{"q":"L'équation (2x − 1)/(x + 3) = 1 a pour condition d'existence :","r":["x ≠ −3","x ≠ 1/2","x ≠ 3","aucune condition"],"b":0,"e":"Le dénominateur x + 3 ne doit pas s'annuler, donc x ≠ −3."},{"q":"(2x − 1)/(x + 3) = 1 a pour solution :","r":["x = −4","x = 4","x = 1/2","x = 3"],"b":1,"e":"2x − 1 = x + 3 donne x = 4, qui est bien différent de −3."},{"q":"Une fonction homographique s'écrit :","r":["ax² + bx + c avec a ≠ 0 et c ≠ 0","ax + b","(ax + b)/(cx + d) avec c ≠ 0","√x"],"b":2,"e":"C'est un quotient de deux expressions du premier degré."},{"q":"(x + 2)/(x − 1) = 0 a pour solution :","r":["x = 1","x = 2","aucune","x = −2"],"b":3,"e":"Un quotient est nul si son numérateur est nul et son dénominateur non nul."},{"q":"Pour résoudre (x + 1)/(x − 2) ≥ 0, on utilise :","r":["un tableau de signes","la seule calculatrice","le discriminant","la dérivée"],"b":0,"e":"On étudie le signe du numérateur et celui du dénominateur."},{"q":"(x + 1)/(x − 2) ≥ 0 a pour solutions :","r":["[−1 ; 2] ∪ ]2 ; +∞[ privé de 0","]−∞ ; −1] ∪ ]2 ; +∞[","]−1 ; 2[","ℝ"],"b":1,"e":"Le quotient est positif à l'extérieur de −1 et 2, et 2 est exclu."},{"q":"Le coût moyen (500x + 10 000)/x vaut 600 pour :","r":["x = 10","x = 1 000","x = 100","x = 50"],"b":2,"e":"500x + 10 000 = 600x donne 100x = 10 000, donc x = 100."},{"q":"Dans une inéquation avec quotient, on ne peut pas multiplier par le dénominateur sans :","r":["le simplifier","le doubler","le mettre au carré","connaître son signe"],"b":3,"e":"Multiplier par un nombre négatif changerait le sens de l'inégalité."},{"q":"La valeur interdite de 3/(2x − 4) est :","r":["x = 2","x = −2","x = 4","x = 3"],"b":0,"e":"2x − 4 = 0 pour x = 2."},{"q":"1/(x − 3) &lt; 0 a pour solutions :","r":["x > 3","x &lt; 3","x = 3","aucune"],"b":1,"e":"Le quotient est négatif lorsque le dénominateur est négatif."}],"c":"1re A","m":"maths","rang":1,"apc":{"module":"Mathématiques de Première A","famille":"Organisation des données et prise de décision dans la vie économique et sociale","agir":"Modéliser des situations de la vie courante pour prendre des décisions","situation":"Le prix moyen d'un article d'une couturière de Mokolo est (2x + 3 000)/x pour x articles, en milliers de francs.","tache":"Pour combien d'articles ce prix moyen vaut-il 5 ?"},"gratuit":true});
VRT_L("1re-a-maths-r02",{"duree":20,"titre":"Tableau des signes d'un quotient","accroche":"Le signe d'un quotient suit la règle des signes.","intro":"Pour résoudre une inéquation avec un quotient, on étudie séparément le numérateur et le dénominateur.","objectifs":["étudier le signe de ax + b","dresser un tableau de signes","conclure"],"parties":[{"t":"Signe de ax + b","html":"<div class='def'><b>Définition</b>L'expression <strong>ax + b</strong> (a ≠ 0) s'annule en −b/a ; elle a le signe de a à droite de cette valeur et le signe contraire à gauche.</div>"},{"t":"Exemple","verrou":true},{"t":"Rédaction","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"1re A","m":"maths","rang":2,"apc":{"module":"Mathématiques de Première A","famille":"Organisation des données et prise de décision dans la vie économique et sociale","agir":"Modéliser des situations de la vie courante pour prendre des décisions","situation":"Un commerçant de Bafang étudie le signe du rapport (x − 3)/(2 − x) pour savoir quand sa marge est positive.","tache":"Donne l'ensemble des valeurs favorables."},"verrou":true,"nq":10,"labo":true});
VRT_L("1re-a-maths-r03",{"duree":20,"titre":"Équations du second degré","accroche":"Le discriminant décide.","intro":"Les équations du second degré apparaissent dès qu'on calcule une aire ou une recette.","objectifs":["calculer le discriminant","résoudre l'équation","vérifier les solutions"],"parties":[{"t":"Le discriminant","html":"<div class='def'><b>Définition</b>Pour ax² + bx + c = 0 (a ≠ 0), <strong>Δ = b² − 4ac</strong>. Si Δ > 0, deux solutions (−b ± √Δ)/(2a) ; si Δ = 0, une solution −b/(2a) ; si Δ &lt; 0, aucune solution réelle.</div>"},{"t":"Exemple","verrou":true},{"t":"Cas simples","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"1re A","m":"maths","rang":3,"apc":{"module":"Mathématiques de Première A","famille":"Organisation des données et prise de décision dans la vie économique et sociale","agir":"Modéliser des situations de la vie courante pour prendre des décisions","situation":"Un jardin rectangulaire à Bertoua a une aire de 24 m², et sa longueur dépasse sa largeur de 2 m.","tache":"Trouve ses dimensions."},"verrou":true,"nq":10,"labo":true});
VRT_L("1re-a-maths-r04",{"duree":20,"titre":"Signe du trinôme ax² + bx + c","accroche":"Le signe de a à l'extérieur des racines.","intro":"Connaître le signe d'un trinôme permet de résoudre les inéquations et d'étudier un bénéfice.","objectifs":["trouver les racines","appliquer la règle du signe","dresser un tableau"],"parties":[{"t":"La règle","html":"<div class='def'><b>Définition</b>Un trinôme a le <strong>signe de a</strong> à l'extérieur de ses racines et le <strong>signe contraire</strong> entre ses racines. S'il n'a pas de racine, il a toujours le signe de a.</div>"},{"t":"Exemple","verrou":true},{"t":"Sans racine","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"1re A","m":"maths","rang":4,"apc":{"module":"Mathématiques de Première A","famille":"Organisation des données et prise de décision dans la vie économique et sociale","agir":"Modéliser des situations de la vie courante pour prendre des décisions","situation":"Le bénéfice d'une vendeuse de jus à Garoua est B(x) = −x² + 4x − 3, en milliers de francs, pour x centaines de bouteilles.","tache":"Pour quelles quantités est-il positif ?"},"verrou":true,"nq":10,"labo":true});
VRT_L("1re-a-maths-r05",{"duree":20,"titre":"Inéquations du second degré","accroche":"Utiliser le signe du trinôme.","intro":"Une inéquation du second degré se résout en lisant le tableau de signes du trinôme.","objectifs":["ramener à une comparaison avec 0","trouver les racines","écrire l'ensemble solution"],"parties":[{"t":"Méthode","html":"<div class='def'><b>Définition</b>Pour résoudre <strong>ax² + bx + c ≤ 0</strong>, on cherche les racines puis on applique la règle du signe du trinôme.</div>"},{"t":"Exemple","verrou":true},{"t":"Crochets","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"1re A","m":"maths","rang":5,"apc":{"module":"Mathématiques de Première A","famille":"Organisation des données et prise de décision dans la vie économique et sociale","agir":"Modéliser des situations de la vie courante pour prendre des décisions","situation":"Une association de Dschang veut que sa recette R(x) = −x² + 10x dépasse 21 milliers de F.","tache":"Pour quelles valeurs de x est-ce le cas ?"},"verrou":true,"nq":10,"labo":true});
VRT_L("1re-a-maths-r06",{"duree":20,"titre":"Systèmes d'équations du premier degré","accroche":"Deux inconnues, deux informations.","intro":"Un système de deux équations permet de retrouver deux quantités inconnues, comme des prix ou des effectifs.","objectifs":["résoudre par substitution","résoudre par combinaison","vérifier la solution"],"parties":[{"t":"Définition","html":"<div class='def'><b>Définition</b>Un <strong>système</strong> de deux équations du premier degré à deux inconnues se résout par substitution ou par combinaison ; si son déterminant est non nul, il a une solution unique.</div>"},{"t":"Exemple","verrou":true},{"t":"Vérification","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"1re A","m":"maths","rang":6,"apc":{"module":"Mathématiques de Première A","famille":"Organisation des données et prise de décision dans la vie économique et sociale","agir":"Modéliser des situations de la vie courante pour prendre des décisions","situation":"Pour un spectacle au palais des congrès, 120 billets ont été vendus pour 95 000 F : 1 000 F l'adulte, 500 F l'enfant.","tache":"Combien d'adultes et d'enfants ?"},"verrou":true,"nq":10,"labo":true});
VRT_L("1re-a-maths-r07",{"duree":20,"titre":"Intégration : bénéfice d'un petit commerce","accroche":"Vendre ni trop ni trop peu.","intro":"Cette séance mobilise les notions du chapitre pour résoudre une situation de la vie courante, comme à la partie B de l'épreuve.","objectifs":["identifier le problème","choisir l'outil mathématique","conclure par une phrase"],"parties":[{"t":"L'outil","html":"<div class='def'><b>Définition</b>Le <strong>bénéfice</strong> est la recette moins le coût ; quand il est un trinôme, on étudie son signe.</div>"},{"t":"La démarche","verrou":true},{"t":"Un exemple","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"1re A","m":"maths","rang":7,"apc":{"module":"Mathématiques de Première A","famille":"Organisation des données et prise de décision dans la vie économique et sociale","agir":"Modéliser des situations de la vie courante pour prendre des décisions","situation":"Une vendeuse de beignets de Kumba modélise son bénéfice par B(x) = −x² + 12x − 20 (milliers de F, x centaines de beignets).","tache":"Pour quelles quantités gagne-t-elle de l'argent ?"},"verrou":true,"nq":10,"labo":true});
VRT_L("1re-a-maths-r08",{"duree":20,"titre":"Compléments sur les ensembles finis","accroche":"Compter sans compter deux fois.","intro":"Pour dénombrer, on organise les éléments en ensembles et on utilise des formules simples.","objectifs":["calculer le cardinal d'une réunion","utiliser le complémentaire","utiliser le produit cartésien"],"parties":[{"t":"Cardinal","html":"<div class='def'><b>Définition</b>Le <strong>cardinal</strong> d'un ensemble fini est son nombre d'éléments. <strong>Card(A ∪ B) = Card A + Card B − Card(A ∩ B)</strong>.</div>"},{"t":"Exemple","verrou":true},{"t":"Produit cartésien","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"1re A","m":"maths","rang":8,"apc":{"module":"Mathématiques de Première A","famille":"Organisation des données et prise de décision dans la vie économique et sociale","agir":"Modéliser des situations de la vie courante pour prendre des décisions","situation":"Dans un quartier de Yaoundé, 60 familles ont la télévision, 45 la radio et 30 les deux ; le quartier compte 90 familles.","tache":"Combien de familles n'ont ni télévision ni radio ?"},"verrou":true,"nq":10,"labo":true});
VRT_L("1re-a-maths-r09",{"duree":20,"titre":"p-listes d'éléments d'un ensemble","accroche":"Ordre et répétition permis.","intro":"Une p-liste est une suite ordonnée de p éléments, avec répétition possible.","objectifs":["reconnaître une p-liste","calculer nᵖ","appliquer à un code"],"parties":[{"t":"Définition","html":"<div class='def'><b>Définition</b>Une <strong>p-liste</strong> d'un ensemble à n éléments est une suite ordonnée de p éléments, distincts ou non. Il y en a <strong>nᵖ</strong>.</div>"},{"t":"Exemples","verrou":true},{"t":"Reconnaître","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"1re A","m":"maths","rang":9,"apc":{"module":"Mathématiques de Première A","famille":"Organisation des données et prise de décision dans la vie économique et sociale","agir":"Modéliser des situations de la vie courante pour prendre des décisions","situation":"Un cadenas de bagage acheté au marché Central a 3 roues de 10 chiffres.","tache":"Combien de codes possibles ?"},"verrou":true,"nq":10,"labo":true});
VRT_L("1re-a-maths-r11",{"duree":20,"titre":"p-listes : entraînement","accroche":"Remplir un QCM au hasard.","intro":"Cette séance d'entraînement reprend la notion avec un exercice type d'examen.","objectifs":["reconnaître le type d'exercice","rédiger la méthode","éviter le piège classique"],"parties":[{"t":"Le rappel","html":"<div class='def'><b>À retenir</b>Chaque question est un choix indépendant : on multiplie.</div>"},{"t":"Exercice résolu","verrou":true},{"t":"Le piège à éviter","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"1re A","m":"maths","rang":11,"apc":{"module":"Mathématiques de Première A","famille":"Organisation des données et prise de décision dans la vie économique et sociale","agir":"Modéliser des situations de la vie courante pour prendre des décisions","situation":"Un élève de Mbouda répond au hasard à un QCM de 5 questions à 4 choix.","tache":"Combien de grilles différentes peut-il produire ?"},"verrou":true,"nq":10,"labo":true});
VRT_L("1re-a-maths-r10",{"duree":20,"titre":"Arrangements","accroche":"L'ordre compte, sans répétition.","intro":"Un arrangement modélise un classement ou une attribution de postes différents.","objectifs":["reconnaître un arrangement","calculer Aⁿₚ","appliquer à un bureau"],"parties":[{"t":"Définition","html":"<div class='def'><b>Définition</b>Un <strong>arrangement</strong> de p éléments parmi n est une suite ordonnée de p éléments distincts. Il y en a <strong>n × (n − 1) × … × (n − p + 1)</strong>.</div>"},{"t":"Exemple","verrou":true},{"t":"Reconnaître","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"1re A","m":"maths","rang":10,"apc":{"module":"Mathématiques de Première A","famille":"Organisation des données et prise de décision dans la vie économique et sociale","agir":"Modéliser des situations de la vie courante pour prendre des décisions","situation":"Le club de théâtre d'un lycée de Bafoussam élit un président, un secrétaire et un trésorier parmi 8 membres.","tache":"Combien de bureaux possibles ?"},"verrou":true,"nq":10,"labo":true});
VRT_L("1re-a-maths-r12",{"duree":20,"titre":"Arrangements : entraînement","accroche":"Le tiercé d'une course.","intro":"Cette séance d'entraînement reprend la notion avec un exercice type d'examen.","objectifs":["reconnaître le type d'exercice","rédiger la méthode","éviter le piège classique"],"parties":[{"t":"Le rappel","html":"<div class='def'><b>À retenir</b>Un classement dans l'ordre est un arrangement.</div>"},{"t":"Exercice résolu","verrou":true},{"t":"Le piège à éviter","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"1re A","m":"maths","rang":12,"apc":{"module":"Mathématiques de Première A","famille":"Organisation des données et prise de décision dans la vie économique et sociale","agir":"Modéliser des situations de la vie courante pour prendre des décisions","situation":"Pour le marathon de l'Espoir, un journaliste parie sur les trois premiers dans l'ordre parmi 10 favoris.","tache":"Combien de pronostics possibles ?"},"verrou":true,"nq":10,"labo":true});
VRT_L("1re-a-maths-r13",{"duree":20,"titre":"Permutations","accroche":"Ranger tous les objets.","intro":"Une permutation est un rangement de tous les éléments d'un ensemble.","objectifs":["définir n!","calculer un nombre de rangements","traiter les répétitions"],"parties":[{"t":"Définition","html":"<div class='def'><b>Définition</b>Une <strong>permutation</strong> de n éléments est un rangement de ces n éléments. Il y en a <strong>n! = n × (n − 1) × … × 1</strong> ; par convention 0! = 1.</div>"},{"t":"Exemple","verrou":true},{"t":"Lettres répétées","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"1re A","m":"maths","rang":13,"apc":{"module":"Mathématiques de Première A","famille":"Organisation des données et prise de décision dans la vie économique et sociale","agir":"Modéliser des situations de la vie courante pour prendre des décisions","situation":"Une bibliothécaire de Kribi range 5 livres différents sur une étagère.","tache":"Combien de rangements possibles ?"},"verrou":true,"nq":10,"labo":true});
VRT_L("1re-a-maths-r15",{"duree":20,"titre":"Permutations : entraînement","accroche":"Garder un groupe ensemble.","intro":"Cette séance d'entraînement reprend la notion avec un exercice type d'examen.","objectifs":["reconnaître le type d'exercice","rédiger la méthode","éviter le piège classique"],"parties":[{"t":"Le rappel","html":"<div class='def'><b>À retenir</b>On traite un groupe comme un seul objet, puis on range l'intérieur du groupe.</div>"},{"t":"Exercice résolu","verrou":true},{"t":"Le piège à éviter","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"1re A","m":"maths","rang":15,"apc":{"module":"Mathématiques de Première A","famille":"Organisation des données et prise de décision dans la vie économique et sociale","agir":"Modéliser des situations de la vie courante pour prendre des décisions","situation":"Pour la photo de classe d'un collège de Bamenda, les trois délégués veulent être côte à côte parmi 7 élèves.","tache":"Combien d'alignements possibles ?"},"verrou":true,"nq":10,"labo":true});
VRT_L("1re-a-maths-r14",{"duree":20,"titre":"Combinaisons","accroche":"Choisir un groupe, sans ordre.","intro":"Une combinaison modélise un comité, une équipe, un tirage simultané.","objectifs":["reconnaître une combinaison","calculer C(n ; p)","utiliser les propriétés"],"parties":[{"t":"Définition","html":"<div class='def'><b>Définition</b>Une <strong>combinaison</strong> de p éléments parmi n est une partie à p éléments. Il y en a <strong>C(n ; p) = n!/[p!(n − p)!]</strong>.</div>"},{"t":"Exemple","verrou":true},{"t":"Propriétés","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"1re A","m":"maths","rang":14,"apc":{"module":"Mathématiques de Première A","famille":"Organisation des données et prise de décision dans la vie économique et sociale","agir":"Modéliser des situations de la vie courante pour prendre des décisions","situation":"Un village de la Lékié choisit 3 délégués parmi 8 volontaires pour une réunion.","tache":"Combien de délégations possibles ?"},"verrou":true,"nq":10,"labo":true});
VRT_L("1re-a-maths-r16",{"duree":20,"titre":"Combinaisons : entraînement","accroche":"Des garçons et des filles dans une délégation.","intro":"Cette séance d'entraînement reprend la notion avec un exercice type d'examen.","objectifs":["reconnaître le type d'exercice","rédiger la méthode","éviter le piège classique"],"parties":[{"t":"Le rappel","html":"<div class='def'><b>À retenir</b>Quand on choisit dans deux groupes, on multiplie les combinaisons.</div>"},{"t":"Exercice résolu","verrou":true},{"t":"Le piège à éviter","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"1re A","m":"maths","rang":16,"apc":{"module":"Mathématiques de Première A","famille":"Organisation des données et prise de décision dans la vie économique et sociale","agir":"Modéliser des situations de la vie courante pour prendre des décisions","situation":"Une ONG de Maroua forme une délégation de 2 garçons et 1 fille parmi 6 garçons et 4 filles.","tache":"Combien de délégations possibles ?"},"verrou":true,"nq":10,"labo":true});
VRT_L("1re-a-maths-r17",{"duree":20,"titre":"Intégration : la tontine du quartier","accroche":"Qui reçoit en premier ?","intro":"Cette séance mobilise les notions du chapitre pour résoudre une situation de la vie courante, comme à la partie B de l'épreuve.","objectifs":["identifier le problème","choisir l'outil mathématique","conclure par une phrase"],"parties":[{"t":"L'outil","html":"<div class='def'><b>Définition</b>Le <strong>dénombrement</strong> compte les ordres et les choix possibles.</div>"},{"t":"La démarche","verrou":true},{"t":"Un exemple","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"1re A","m":"maths","rang":17,"apc":{"module":"Mathématiques de Première A","famille":"Organisation des données et prise de décision dans la vie économique et sociale","agir":"Modéliser des situations de la vie courante pour prendre des décisions","situation":"Une tontine de 10 membres à Douala tire au sort l'ordre de passage et élit un bureau (président, secrétaire, trésorier).","tache":"Combien d'ordres de passage et de bureaux possibles ?"},"verrou":true,"nq":10,"labo":true});
VRT_L("1re-a-maths-r18",{"duree":20,"titre":"Parité d'une fonction","accroche":"Une courbe en miroir.","intro":"Une fonction paire ou impaire présente une symétrie qui réduit l'étude de moitié.","objectifs":["vérifier l'ensemble de définition","reconnaître une fonction paire","reconnaître une fonction impaire"],"parties":[{"t":"Définitions","html":"<div class='def'><b>Définition</b>Sur un ensemble symétrique par rapport à 0, f est <strong>paire</strong> si f(−x) = f(x), <strong>impaire</strong> si f(−x) = −f(x).</div>"},{"t":"Interprétation","verrou":true},{"t":"Exemples","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"1re A","m":"maths","rang":18,"apc":{"module":"Mathématiques de Première A","famille":"Organisation des données et prise de décision dans la vie économique et sociale","agir":"Modéliser des situations de la vie courante pour prendre des décisions","situation":"Une créatrice de pagnes à Foumban dessine un motif suivant la courbe y = x⁴ − 2x².","tache":"Le motif est-il symétrique ? Justifie."},"verrou":true,"nq":10,"labo":true});
VRT_L("1re-a-maths-r19",{"duree":20,"titre":"Éléments de symétrie d'une courbe","accroche":"Axe ou centre de symétrie.","intro":"Une courbe peut être symétrique par rapport à une droite verticale ou à un point.","objectifs":["démontrer un axe de symétrie","démontrer un centre de symétrie","exploiter la symétrie"],"parties":[{"t":"Axe","html":"<div class='def'><b>Définition</b>La droite d'équation <strong>x = a</strong> est axe de symétrie de la courbe de f si f(2a − x) = f(x) pour tout x du domaine.</div>"},{"t":"Centre","verrou":true},{"t":"Exemple","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"1re A","m":"maths","rang":19,"apc":{"module":"Mathématiques de Première A","famille":"Organisation des données et prise de décision dans la vie économique et sociale","agir":"Modéliser des situations de la vie courante pour prendre des décisions","situation":"Une arche de portail à Bandjoun suit la courbe y = −x² + 4x.","tache":"Où se trouve l'axe de symétrie de l'arche ?"},"verrou":true,"nq":10,"labo":true});
VRT_L("1re-a-maths-r20",{"duree":20,"titre":"Intégration : un motif symétrique","accroche":"Concevoir un logo équilibré.","intro":"Cette séance mobilise les notions du chapitre pour résoudre une situation de la vie courante, comme à la partie B de l'épreuve.","objectifs":["identifier le problème","choisir l'outil mathématique","conclure par une phrase"],"parties":[{"t":"L'outil","html":"<div class='def'><b>Définition</b>Une <strong>symétrie</strong> de la courbe d'une fonction se démontre par le calcul.</div>"},{"t":"La démarche","verrou":true},{"t":"Un exemple","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"1re A","m":"maths","rang":20,"apc":{"module":"Mathématiques de Première A","famille":"Organisation des données et prise de décision dans la vie économique et sociale","agir":"Modéliser des situations de la vie courante pour prendre des décisions","situation":"Une imprimerie de Douala veut un logo en forme d'arc symétrique d'équation y = x² − 4x + 5.","tache":"Où placer l'axe du logo ?"},"verrou":true,"nq":10,"labo":true});
VRT_L("1re-a-maths-r21",{"duree":20,"titre":"Caractères statistiques discrets","accroche":"Compter les enfants par famille.","intro":"Un caractère discret prend des valeurs isolées ; on le résume par un tableau d'effectifs.","objectifs":["identifier population et caractère","calculer effectifs et fréquences","tracer un diagramme en bâtons"],"parties":[{"t":"Vocabulaire","html":"<div class='def'><b>Définition</b>La <strong>population</strong> est l'ensemble étudié ; le <strong>caractère</strong> est ce que l'on observe. Il est <strong>discret</strong> s'il prend des valeurs isolées, comme un nombre d'enfants.</div>"},{"t":"Exemple","verrou":true},{"t":"Diagramme en bâtons","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"1re A","m":"maths","rang":21,"apc":{"module":"Mathématiques de Première A","famille":"Organisation des données et prise de décision dans la vie économique et sociale","agir":"Modéliser des situations de la vie courante pour prendre des décisions","situation":"Un recensement de quartier à Ebolowa relève le nombre d'enfants de 20 familles.","tache":"Quel diagramme choisir et pourquoi ?"},"verrou":true,"nq":10,"labo":true});
VRT_L("1re-a-maths-r22",{"duree":20,"titre":"Caractères regroupés en classes","accroche":"Des notes de 0 à 20 par tranches.","intro":"Quand les valeurs sont nombreuses, on les regroupe en classes de même amplitude.","objectifs":["regrouper en classes","calculer les centres","tracer un histogramme"],"parties":[{"t":"Définition","html":"<div class='def'><b>Définition</b>Une <strong>classe</strong> [a ; b[ regroupe les valeurs comprises entre a inclus et b exclu ; son <strong>amplitude</strong> est b − a et son <strong>centre</strong> (a + b)/2.</div>"},{"t":"Exemple","verrou":true},{"t":"Histogramme","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"1re A","m":"maths","rang":22,"apc":{"module":"Mathématiques de Première A","famille":"Organisation des données et prise de décision dans la vie économique et sociale","agir":"Modéliser des situations de la vie courante pour prendre des décisions","situation":"Un professeur de Mbalmayo regroupe les notes de ses 30 élèves en classes de 5 points.","tache":"Construis le tableau et identifie la classe modale."},"verrou":true,"nq":10,"labo":true});
